def ensure_instruction_path(path: Path) -> Path:
    """Only allow the known project instruction file for this safe MVP runner."""
    resolved = path.resolve()
    allowed = DEFAULT_INSTRUCTION.resolve()
    if resolved != allowed:
        raise ConfigError(f'Only the MVP instruction file is allowed: {allowed}')
    return resolved


def strip_quotes(value: str) -> str:
    value = value.strip()
    if value.startswith(('"', "'")) and value.endswith(('"', "'")):
        value = value[1:-1]
    return value


def section_block(text: str, section: str) -> str:
    match = re.search(rf'^\s*{re.escape(section)}:\s*$(.*?)(?=^\S|\Z)', text, re.M | re.S)
    if not match:
        raise ConfigError(f'Missing section: {section}')
    return match.group(1)


def scalar(text: str, key: str) -> str | None:
    match = re.search(rf'^\s*{re.escape(key)}:\s*(.+?)\s*$', text, re.M)
    return strip_quotes(match.group(1)) if match else None


def section_scalar(text: str, section: str, key: str) -> str | None:
    block = section_block(text, section)
    match = re.search(rf'^\s*{re.escape(key)}:\s*(.+?)\s*$', block, re.M)
    return strip_quotes(match.group(1)) if match else None


def bool_value(value: str | None, key: str) -> bool | None:
    if value is None:
        return None
    lower = value.lower()
    if lower == 'true':
        return True
    if lower == 'false':
        return False
    raise ConfigError(f'{key} must be true/false, got: {value}')


def bool_section_scalar(text: str, section: str, key: str) -> bool | None:
    return bool_value(section_scalar(text, section, key), f'{section}.{key}')


def int_scalar(text: str, key: str) -> int | None:
    value = scalar(text, key)
    if value is None:
        return None
    try:
        return int(value)
    except ValueError as exc:
        raise ConfigError(f'{key} must be integer, got: {value}') from exc

